/* Fume web kit script (PROPOSED, 13 Oct 2026). GENERATED by kit/build.mjs: touch.js, focus.js, <fume-frame> and <fume-light>. */

// Touch: iOS Safari only shows :active (the pressed state) on tap when the page listens for touches.
// This passive, empty listener is that switch. Load it once per page, with base.css.
document.addEventListener("touchstart", () => {}, { passive: true });

// Focus: the ring is for the keyboard. A field you click or tap into shows its caret, not the ring
// (Marcus 13 Oct: "fokus kommer fra tab eller sånt"). Browsers always match :focus-visible on a text
// field (Chromium on a native select too), however it got focus, so this marks a field focused by a
// pointer with data-ui-focus="pointer" until it loses focus, and the field components turn their ring
// off for it (field, input-group, combobox, composer, input-otp, native select). Tab or Shift+Tab to a
// field and the ring is there; keys pressed outside a field (arrows in a menu, Enter on a button) count
// as the keyboard too.
(() => {
  const FIELD = 'select, input:not([type="checkbox"], [type="radio"], [type="range"], [type="button"], [type="submit"], [type="reset"], [type="file"], [type="color"], [type="image"]), textarea, [contenteditable=""], [contenteditable="true"]';
  const isField = (el) => el instanceof Element && el.matches(FIELD);
  let pointer = false;
  document.addEventListener("pointerdown", () => { pointer = true; }, true);
  document.addEventListener("keydown", (e) => { if (e.key === "Tab" || !isField(e.target)) pointer = false; }, true);
  document.addEventListener("focusin", (e) => {
    if (!isField(e.target)) return;
    if (pointer) e.target.setAttribute("data-ui-focus", "pointer"); else e.target.removeAttribute("data-ui-focus");
  }, true);
  document.addEventListener("focusout", (e) => { if (e.target instanceof Element) e.target.removeAttribute("data-ui-focus"); }, true);
})();

(() => {

const GRAIN_DEFS = "<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\"><filter id=\"fume-grain\" x=\"0\" y=\"0\" width=\"1\" height=\"1\"><feTurbulence type=\"fractalNoise\" baseFrequency=\".9\" numOctaves=\"2\" stitchTiles=\"stitch\"/><feColorMatrix values=\"0 0 0 0 0.106  0 0 0 0 0.078  0 0 0 0 0.063  0 0 0 .55 0\"/></filter></svg>";

// The Focus System geometry for templates: a port of tools/canvas/tools/geo.py (Focus System v1.3, F-D059),
// the same port the brand book's Focus page draws with. Returns SVG markup in the image's own coordinates.
//   Corners from the short side: u = 5% of it / 3; corner 11u, arms 2.5u. Two corners: top-left and bottom-right.
//   The point from the area: 5% of sqrt(w x h). The pointer's tip sits point/3 right of and below its target.
//   On a photograph the corners and the point are Paper, on a light image or a dark one (F-D082, Marcus 13 Oct 2026;
//   it replaces Ink on a really light image, F-D078). Never mixed. Amber is only the check landing, once.
//   The lift is an option, not a rule (Marcus 13 Oct 2026): a Paper point on a light area MAY take one shadow so faint
//   you barely see it is a shadow. The colour picker decides: pick the colour under the point; if Paper reaches less
//   than 3:1 against it, the point may be lifted. Only the point, never the corners or the Amber check, and only on
//   still images: in motion, whoever makes the video judges it on the spot.
const POINT_D = "M225 245C225 234 234 225 245 225H326.7C334.8 225 342.1 229.9 345.2 237.3C348.3 244.8 346.6 253.4 340.9 259.1L259.1 340.9C253.4 346.6 244.8 348.3 237.3 345.2C229.9 342.1 225 334.8 225 326.7Z";
const g6 = (x) => String(+(+x).toPrecision(6));

// The lift, sized from the frame's u so it is the same at every size: one soft Ink shadow, straight down
// (.fume-focus-lift { flood-color: Ink }). As little as it takes; nothing else ever touches the frame.
const LIFT = { down: 0.2, blur: 1, opacity: 0.35 };
// The filter for one point; the region is the whole image, so the shadow is never cut off around a small point.
function liftFilter(id, u) {
  return `<filter id="${id}" filterUnits="userSpaceOnUse" x="-9999" y="-9999" width="19999" height="19999" color-interpolation-filters="sRGB">` +
    `<feGaussianBlur in="SourceAlpha" stdDeviation="${g6(LIFT.blur * u)}"/><feOffset dy="${g6(LIFT.down * u)}" result="o"/>` +
    `<feFlood class="fume-focus-lift" flood-opacity="${LIFT.opacity}"/><feComposite in2="o" operator="in" result="s"/>` +
    `<feMerge><feMergeNode in="s"/><feMergeNode in="SourceGraphic"/></feMerge></filter>`;
}
// The colour picker: Paper's contrast against the colour under the point. Below 3:1 the point may be lifted.
const lin = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
const luminance = ([r, g, b]) => 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
const LIFT_BELOW = 3;
function paperContrast(under, paper = [252, 246, 235]) {
  const a = luminance(paper), b = luminance(under);
  return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
}
const mayLift = (under) => paperContrast(under) < LIFT_BELOW;
let lifts = 0;
const f2 = (x) => x.toFixed(2);

function poly(pts, r) {
  const n = pts.length; let d = "";
  const toward = (a, b, dd) => { const dx = b[0] - a[0], dy = b[1] - a[1], l = Math.hypot(dx, dy); dd = Math.min(dd, l / 2); return [a[0] + dx / l * dd, a[1] + dy / l * dd]; };
  for (let i = 0; i < n; i++) {
    const p0 = pts[(i - 1 + n) % n], p1 = pts[i], p2 = pts[(i + 1) % n];
    const a = toward(p1, p0, r), b = toward(p1, p2, r);
    d += (i ? "L" : "M") + f2(a[0]) + " " + f2(a[1]) + " Q" + f2(p1[0]) + " " + f2(p1[1]) + " " + f2(b[0]) + " " + f2(b[1]);
  }
  return d + "Z";
}
function cornerD(u, logo) {
  let t, g, r;
  if (logo) { t = 3 * u; g = u; r = 0.4 * u; } else { t = 2.5 * u; g = t / 3; r = 0.1 * t; }
  const L = 11 * u;
  return poly([[0, 0], [L, 0], [L - t, t], [0, t]], r) + poly([[0, t + g], [t, t + g], [t, L - t], [0, L]], r);
}
const ptTransform = (tip, P, rot) => `translate(${g6(tip[0])} ${g6(tip[1])}) rotate(${rot}) scale(${g6(P / 150)}) translate(-225 -225)`;
const pointSvg = (tip, P, cls, rot = 0) => `<path class="${cls}" d="${POINT_D}" transform="${ptTransform(tip, P, rot)}"/>`;
// sc "1 1" is the top-left corner, "-1 -1" the bottom-right one
const cornerSvg = (xy, u, cls, sc = "1 1", logo = false) => `<path class="${cls}" d="${cornerD(u, logo)}" transform="translate(${g6(xy[0])} ${g6(xy[1])}) scale(${sc})"/>`;
const focalTip = (cx, cy, P) => [cx, cy - P * Math.SQRT2 / 3];
const pointerTip = (tx, ty, P) => [tx + P / 3, ty + P / 3];

// A frame from its box: both corners, the sizes, and where its point goes.
function frame(x0, y0, x1, y1) {
  const w = x1 - x0, h = y1 - y0, u = 0.05 * Math.min(w, h) / 3, P = 0.05 * Math.sqrt(w * h);
  return { x0, y0, x1, y1, w, h, u, P, cx: (x0 + x1) / 2, cy: (y0 + y1) / 2,
    corners: (cls) => cornerSvg([x0, y0], u, cls, "1 1") + cornerSvg([x1, y1], u, cls, "-1 -1") };
}

// The whole overlay for one image: two Paper corners and one point.
//   box: [x0, y0, x1, y1] as fractions of the image;
//   point: "focal" (the Engine at work), "pointer" (the expert at work) or "check" (Amber, the check landing);
//   target: [x, y] fractions, what the pointer or the check points at;
//   lift: true lifts a Paper point (the colour picker said Paper reaches less than 3:1 under it, see mayLift).
// Returns { svg, tip, P } so a caller can place a tag such as "Checked by Anna" beside the tip.
function overlay(W, H, { box, point = "check", target, lift = false } = {}) {
  const F = frame(box[0] * W, box[1] * H, box[2] * W, box[3] * H);
  const cls = "fume-focus-paper";
  let tip, rot = 0;
  if (point === "focal" || !target) { tip = focalTip(F.cx, F.cy, F.P); rot = 45; }
  else tip = pointerTip(target[0] * W, target[1] * H, F.P);
  let pt = pointSvg(tip, F.P, point === "check" ? "fume-focus-check" : cls, rot);
  if (lift && point !== "check") { const id = `fume-lift-${++lifts}`; pt = liftFilter(id, F.u) + `<g filter="url(#${id})">${pt}</g>`; }
  return { svg: F.corners(cls) + pt, tip, P: F.P, frame: F };
}

// Brand light for decks and marketing grounds: the Light board L1 to L5 (DECIDED 7 Oct 2026), drawn in palette tokens.
// One Amber light source per surface, from an edge or a corner, on a light ground, with the grain.
// Never on Ink or Brown, and never behind small text. L1 is the default; L2 to L5 for covers and campaign moments.
// Shapes are the board's own, in its 800 x 480 space; the SVG covers its box (slice), so any 16:9 or 4:5 crop works.
// mirror: true flips it left to right, so the source can sit in the other corner.
const SHAPES = {
  L1: `<ellipse cx="800" cy="0" rx="280" ry="168" class="fume-light-soft" filter="url(#fume-light-wide)" opacity=".6"/>`,
  L2: `<path d="M-100 456 C 150 264, 300 432, 520 216 S 820 24, 960 -40 L 960 168 C 800 288, 600 192, 420 408 S 80 528, -100 576 Z" class="fume-light-warm" filter="url(#fume-light-wide)" opacity=".9"/>` +
      `<path d="M-60 480 C 200 297, 340 456, 560 240 S 800 72, 900 24" class="fume-light-core" stroke-width="60" fill="none" filter="url(#fume-light-narrow)" opacity=".85"/>`,
  L3: `<ellipse cx="40" cy="504" rx="440" ry="288" class="fume-light-warm" filter="url(#fume-light-wide)"/>` +
      `<ellipse cx="0" cy="552" rx="240" ry="168" class="fume-light-amber" filter="url(#fume-light-wide)" opacity=".8"/>`,
  L5: `<rect x="-120" y="400" width="1040" height="200" class="fume-light-soft" filter="url(#fume-light-wide)"/>` +
      `<ellipse cx="400" cy="489" rx="360" ry="57" class="fume-light-amber" filter="url(#fume-light-wide)" opacity=".7"/>`,
};
const GROUND = { L1: "fume-light-ground-paper", L2: "fume-light-ground-paper", L3: "fume-light-ground-cream", L5: "fume-light-ground-paper" };
const LIGHTS = Object.keys(SHAPES);

const LIGHT_DEFS = `<svg width="0" height="0" style="position:absolute" aria-hidden="true">` +
  `<filter id="fume-light-wide" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="70"/></filter>` +
  `<filter id="fume-light-narrow" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="38"/></filter></svg>`;

function light(name = "L1", { mirror = false, cls = "fume-light" } = {}) {
  if (!SHAPES[name]) throw new Error(`Unknown light ${name}; use ${LIGHTS.join(", ")}.`);
  const flip = mirror ? ` transform="translate(800 0) scale(-1 1)"` : "";
  return `<svg class="${cls}" viewBox="0 0 800 480" preserveAspectRatio="xMidYMid slice" aria-hidden="true">` +
    `<rect width="800" height="480" class="${GROUND[name]}"/><g${flip}>${SHAPES[name]}</g>` +
    `<rect width="800" height="480" filter="url(#fume-grain)" opacity=".22"/></svg>`;
}

// Fills by token. L5's warm floor is a soft band of the same light, not a colour gradient.
const LIGHT_CSS = `
.fume-light-ground-paper { fill: var(--fume-paper); }
.fume-light-ground-cream { fill: var(--fume-cream); }
.fume-light-soft { fill: var(--fume-amber-100); }
.fume-light-warm { fill: var(--fume-amber-200); }
.fume-light-amber { fill: var(--fume-amber); }
.fume-light-core { stroke: var(--fume-amber); }
`;

// <fume-frame>: the Focus frame over an image, drawn with the same geometry as the brand book and the templates
// (templates/lib/focus.mjs, Focus System v1.3). Wrap the image; the frame redraws when the image changes size.
//   <fume-frame box="0.2 0.15 0.8 0.85" point="check" target="0.56 0.42">
//     <img src="..." alt="...">
//   </fume-frame>
// box: the frame's corners as fractions of the image (x0 y0 x1 y1). point: "check" (Amber, the check landing; only on
// a dark area), "pointer" (the expert at work) or "focal" (the Engine at work). target: what the pointer or the check
// points at, as fractions. lift: present to give a Paper point the faint shadow (only where Paper reaches less than
// 3:1 against the colour under it; an option, not a rule). Corners and point are Paper on a photograph (F-D082).
// The build (kit/build.mjs) puts focus.mjs in front of this file.
class FumeFrame extends HTMLElement {
  static get observedAttributes() { return ["box", "point", "target", "lift"]; }
  connectedCallback() {
    this.svg ||= this.appendChild(document.createElementNS("http://www.w3.org/2000/svg", "svg"));
    this.svg.setAttribute("aria-hidden", "true");
    this.ro ||= new ResizeObserver(() => this.draw());
    this.ro.observe(this);
    this.draw();
  }
  disconnectedCallback() { if (this.ro) this.ro.disconnect(); }
  attributeChangedCallback() { if (this.svg) this.draw(); }
  nums(name, fallback) {
    const v = (this.getAttribute(name) || "").trim().split(/[\s,]+/).map(Number);
    return v.length === fallback.length && v.every(Number.isFinite) ? v : fallback;
  }
  draw() {
    const W = this.clientWidth, H = this.clientHeight;
    if (!W || !H) return;
    const point = this.getAttribute("point") || "check";
    const target = this.hasAttribute("target") ? this.nums("target", [0.5, 0.5]) : undefined;
    const ov = overlay(W, H, { box: this.nums("box", [0.12, 0.12, 0.88, 0.88]), point, target, lift: this.hasAttribute("lift") });
    this.svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
    this.svg.innerHTML = ov.svg;
  }
}
if (!customElements.get("fume-frame")) customElements.define("fume-frame", FumeFrame);

// <fume-light>: the brand light behind a Paper section, drawn from the Light board (templates/lib/light.mjs, L1 to L5,
// DECIDED 7 Oct 2026) with the brand grain, the same as the deck. Put it first in a .web-section--warm
// .web-section--light; it fills the section behind the content.
//   <fume-light name="L1"></fume-light>   L1 (the default, a soft wash from the top-right corner), L2, L3 or L5
//   mirror                                 puts the source in the other corner
// One light per view, on Paper only: never on Brown or Ink, never behind small text.
// The build (kit/build.mjs) puts light.mjs and the grain's filter in front of this file.
class FumeLight extends HTMLElement {
  static get observedAttributes() { return ["name", "mirror"]; }
  connectedCallback() {
    if (!document.getElementById("fume-light-wide")) document.body.insertAdjacentHTML("afterbegin", LIGHT_DEFS);
    if (!document.getElementById("fume-grain")) document.body.insertAdjacentHTML("afterbegin", GRAIN_DEFS);
    this.setAttribute("aria-hidden", "true");
    this.draw();
  }
  attributeChangedCallback() { if (this.isConnected) this.draw(); }
  draw() {
    const name = this.getAttribute("name") || "L1";
    this.innerHTML = light(LIGHTS.includes(name) ? name : "L1", { mirror: this.hasAttribute("mirror") });
  }
}
if (!customElements.get("fume-light")) customElements.define("fume-light", FumeLight);

})();
